#!/bin/bash
# Generate the web UI TLS key + CSR for submission to the internal PKI (pki.example.net).
#
#   sudo ./deploy/make-csr.sh [--rsa] [--name radius.example.net] [--ip 192.0.2.x] [--force]
#
# Key: ECDSA P-384 (default) or RSA-3072 (--rsa), generated by OpenSSL 3 (FIPS provider
# when the kernel is in FIPS mode). The private key never leaves this host:
#   /etc/radius-admin/tls/server.key  root:root 0600
#   /etc/radius-admin/tls/server.csr  (submit this; request a "TLS Web Server" template,
#                                      EKU serverAuth, SHA-256 or SHA-384 signature)
# Install the issued certificate (leaf, then Example-IssuingCA) as
#   /etc/radius-admin/tls/server.crt
# then run: sudo ./deploy/install.sh --phase nginx
set -euo pipefail
umask 077

NAME=radius.example.net
IP=""
ALG=ec
FORCE=0
DIR=/etc/radius-admin/tls
while [[ $# -gt 0 ]]; do
    case $1 in
        --rsa) ALG=rsa; shift ;;
        --name) NAME=$2; shift 2 ;;
        --ip) IP=$2; shift 2 ;;
        --dir) DIR=$2; shift 2 ;;
        --force) FORCE=1; shift ;;
        -h|--help) sed -n '2,15p' "$0" | sed 's/^# \{0,1\}//'; exit 0 ;;
        *) echo "unknown option $1" >&2; exit 2 ;;
    esac
done
[[ ${EUID:-$(id -u)} -eq 0 ]] || { echo "run as root" >&2; exit 1; }
[[ $NAME =~ ^[A-Za-z0-9.-]+$ ]] || { echo "invalid --name" >&2; exit 2; }
[[ -z $IP || $IP =~ ^[0-9]+\.[0-9]+\.[0-9]+\.[0-9]+$ ]] || { echo "invalid --ip" >&2; exit 2; }

if [[ $(cat /proc/sys/crypto/fips_enabled 2>/dev/null || echo 0) != 1 ]]; then
    echo "WARNING: kernel FIPS mode is not enabled on this host" >&2
fi

install -d -o root -g root -m 0700 "$DIR"
KEY=$DIR/server.key
CSR=$DIR/server.csr
if [[ -e $KEY && $FORCE -eq 0 ]]; then
    echo "$KEY already exists; re-using it for a new CSR (use --force for a new key)"
else
    TMP=$(mktemp "$DIR/.server.key.XXXXXX")
    if [[ $ALG == ec ]]; then
        openssl genpkey -algorithm EC -pkeyopt ec_paramgen_curve:P-384 -pkeyopt ec_param_enc:named_curve -out "$TMP"
    else
        openssl genpkey -algorithm RSA -pkeyopt rsa_keygen_bits:3072 -out "$TMP"
    fi
    chown root:root "$TMP"; chmod 0600 "$TMP"
    mv -f "$TMP" "$KEY"
    echo "new private key: $KEY"
fi

SAN="DNS:$NAME"
[[ -n $IP ]] && SAN="$SAN,IP:$IP"
openssl req -new -sha384 -key "$KEY" -out "$CSR" \
    -subj "/CN=$NAME" \
    -addext "subjectAltName=$SAN" \
    -addext "keyUsage=critical,digitalSignature$([[ $ALG == rsa ]] && echo ',keyEncipherment')" \
    -addext "extendedKeyUsage=serverAuth"
chmod 0644 "$CSR"
openssl req -in "$CSR" -noout -verify >/dev/null
echo
openssl req -in "$CSR" -noout -subject -text | grep -E 'Subject:|Public Key Algorithm|NIST CURVE|Public-Key|DNS:|Signature Algorithm' | sort -u
echo
echo "CSR: $CSR  (submit to pki.example.net)"
echo "Then install the issued chain as $DIR/server.crt (root:root 0644) and run: install.sh --phase nginx"
